def check_LO_mode_correctness(schedule, task_set):
    for job in schedule.jobs_in_LO_mode:
        task = job.task
        if task.chi == 'HI':
            if job.actual_execution_time > task.C_LO:
                return False # HI task overran C_LO in LO mode
        else: # LO task
            if job.actual_execution_time > task.C:
                return False # LO task overran C in LO mode
        if job.completion_time > job.absolute_deadline:
            return False # Deadline miss
    return True

def check_HI_mode_correctness(schedule, task_set):
    for job in schedule.jobs_in_HI_mode:
        task = job.task
        if task.chi == 'HI':
            if job.actual_execution_time > task.C_HI:
                return False # HI task overran C_HI in HI mode
            if job.completion_time > job.absolute_deadline:
                return False # HI task deadline miss
        else: # LO task
            # This part requires tracking admitted jobs over windows
            # (e.g., using Algorithm 1's logic)
            pass # Assume admission control ensures r_i * N jobs are admitted
    # Additional check for LO tasks: verify r_i * N completion for all N
    return True

class AdmissionController:
    def __init__(self, task_set_LO):
        self.admitted_counts = {task.id: 0 for task in task_set_LO}
        self.job_release_counts = {task.id: 0 for task in task_set_LO}

    def process_job_release(self, job):
        task_id = job.task.id
        if job.task.chi == 'LO':
            self.job_release_counts[task_id] += 1
            b = self.job_release_counts[task_id]
            r_i = job.task.r
            a_i = self.admitted_counts[task_id]

            if a_i < b * r_i:
                # Admit job for scheduling
                self.admitted_counts[task_id] += 1
                return True # Job admitted
            else:
                # Drop job
                return False # Job dropped
        return True # HI-criticality jobs are always admitted

def calculate_max_consecutive_drops(r_i):
    if r_i == 0:
        return float('inf') # All jobs can be dropped
    if r_i == 1:
        return 0 # No jobs can be dropped
    return (1 / r_i) - 1

def dbf_LO_LO(tau_i, delta):
    if delta < tau_i.D:
        return 0
    num_jobs = floor((delta - tau_i.D) / tau_i.T) + 1
    return num_jobs * tau_i.C

def dbf_LO_HI(tau_i, delta):
    # Assuming tau_i.D_v is the virtual deadline for HI tasks
    if delta < tau_i.D_v:
        return 0
    num_jobs = floor((delta - tau_i.D_v) / tau_i.T) + 1
    return num_jobs * tau_i.C_LO

def is_edf_schedulable_classic(task_set, max_delta_to_check):
    for delta in range(0, max_delta_to_check + 1):
        total_demand = 0
        for tau_i in task_set:
            # Assuming a generic dbf_standard function for non-MC tasks
            total_demand += dbf_standard(tau_i, delta)
        if total_demand > delta:
            return False
    return True

def dbf_HI_LO(tau_i, delta, Num_i_func):
    if delta < tau_i.D:
        return 0
    potential_jobs = floor((delta - tau_i.D) / tau_i.T) + 1
    admitted_jobs = Num_i_func(potential_jobs, tau_i.r) # Num_i_func depends on r_i
    return admitted_jobs * tau_i.C

def full(tau_i, delta):
    effective_deadline_offset = tau_i.D - tau_i.D_v
    if delta < effective_deadline_offset:
        return 0
    num_jobs = floor((delta - effective_deadline_offset) / tau_i.T) + 1
    return num_jobs * tau_i.C_HI

def done(tau_i, delta):
    rho = delta % tau_i.T
    if tau_i.D > rho and rho >= (tau_i.D - tau_i.D_v):
        return max(0, tau_i.C_LO - rho + tau_i.D - tau_i.D_v)
    else:
        return 0

def is_edf_gvd_schedulable(task_set_LO, task_set_HI, max_delta_to_check, Num_i_func):
    # Check Condition A (LO Mode)
    for delta in range(0, max_delta_to_check + 1):
        demand_A = 0
        for tau_i_LO in task_set_LO:
            demand_A += dbf_LO_LO(tau_i_LO, delta)
        for tau_i_HI in task_set_HI:
            demand_A += dbf_LO_HI(tau_i_HI, delta)
        if demand_A > delta:
            return False # Condition A failed

    # Check Condition B (HI Mode)
    for delta in range(0, max_delta_to_check + 1):
        demand_B = 0
        for tau_i_LO in task_set_LO:
            demand_B += dbf_HI_LO(tau_i_LO, delta, Num_i_func)
        for tau_i_HI in task_set_HI:
            demand_B += dbf_HI_HI(tau_i_HI, delta)
        if demand_B > delta:
            return False # Condition B failed

    return True # Both conditions passed

def calculate_delta_bound_B(task_set_LO, task_set_HI):
    U_HI_LO_mode = 0
    max_offset_LO_HI_mode = 0
    for tau_i_LO in task_set_LO:
        if tau_i_LO.r > 0:
            U_HI_LO_mode += tau_i_LO.r * tau_i_LO.C / tau_i_LO.T
            max_offset_LO_HI_mode = max(max_offset_LO_HI_mode, tau_i_LO.T - tau_i_LO.D + tau_i_LO.T / tau_i_LO.r)

    U_HI_HI_mode = 0
    max_offset_HI_HI_mode = 0
    for tau_i_HI in task_set_HI:
        U_HI_HI_mode += tau_i_HI.C_HI / tau_i_HI.T
        max_offset_HI_HI_mode = max(max_offset_HI_HI_mode, tau_i_HI.T - tau_i_HI.D + tau_i_HI.D_v)

    total_utilization_HI_mode = U_HI_LO_mode + U_HI_HI_mode
    if total_utilization_HI_mode >= 1:
        return float('inf')

    numerator = U_HI_LO_mode * max_offset_LO_HI_mode + U_HI_HI_mode * max_offset_HI_HI_mode
    denominator = 1 - total_utilization_HI_mode

    bound_delta = numerator / denominator
    return bound_delta

def calculate_L1_idle_bound(task_set_LO, task_set_HI):
    numerator_sum_C = 0
    denominator_sum_U = 0

    for tau_i_HI in task_set_HI:
        numerator_sum_C += tau_i_HI.C_LO
        denominator_sum_U += tau_i_HI.C_LO / tau_i_HI.T

    for tau_i_LO in task_set_LO:
        numerator_sum_C += tau_i_LO.r * tau_i_LO.C
        denominator_sum_U += tau_i_LO.r * tau_i_LO.C / tau_i_LO.T

    if (1 - denominator_sum_U) <= 0:
        return float('inf') # System is not stable, can be busy forever

    L_1 = numerator_sum_C / (1 - denominator_sum_U)
    return L_1
